import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const b=JSON.parse('{"title":"数学基础","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/数学基础.md","filePath":"专业基础/数学基础.md","lastUpdated":1792430298000}'),l={name:"专业基础/数学基础.md"};function o(i,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="数学基础" tabindex="-1">数学基础 <a class="header-anchor" href="#数学基础" aria-label="Permalink to &quot;数学基础&quot;">​</a></h1><blockquote><p>网安专业的数学主线是「离散 → 数论 → 密码学」。校内课程包括线性代数、概率论与数理统计、离散数学与信息安全数学基础，它们是密码学与协议分析的地基。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li><strong>信息安全数学基础</strong>（第 3 学期）→ <strong>现代密码学</strong>（第 3 学期）是专业最核心的一条线；</li><li>数论（同余、群环域、素性测试）直接就是 RSA、ECC 等公钥体制的底层；</li><li>概率论支撑侧信道分析、随机性安全；线性代数支撑格密码等前沿方向。</li></ul><h2 id="课程脉络" tabindex="-1">课程脉络 <a class="header-anchor" href="#课程脉络" aria-label="Permalink to &quot;课程脉络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>校内阶段</th><th>在网安中的用处</th></tr></thead><tbody><tr><td>高等数学 / 线性代数</td><td>大一</td><td>通用数学素养，后续课程工具</td></tr><tr><td>离散数学</td><td>大二</td><td>逻辑、集合、图论——协议与算法的语言</td></tr><tr><td>概率论与数理统计</td><td>大二</td><td>安全归约、随机性、统计推断</td></tr><tr><td>信息安全数学基础</td><td>第 3 学期</td><td>数论与抽象代数，直通密码学</td></tr></tbody></table><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《信息安全数学基础》教材（校内指定）</td><td>教材</td><td>以校内教材为主线</td></tr><tr><td>MIT 6.042J: Mathematics for Computer Science</td><td>公开课</td><td>计算机科学数学（离散）经典课，中文讲义社区可查</td></tr><tr><td>MIT 18.06: Linear Algebra（Gilbert Strang）</td><td>公开课</td><td>线性代数经典，B 站有带字幕搬运</td></tr><tr><td>《密码学中的数论》</td><td>拓展</td><td>想深入公钥密码时再读</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>数学课<strong>跟着校内进度走</strong>，别等用到才补——密码学课上现学数论会非常吃力；</li><li>「信息安全数学基础」务必当主线课认真学，它是后面 <a href="./../安全方向/密码学.html">密码学</a> 与 <a href="./../安全方向/安全协议分析.html">安全协议分析</a> 的入场券；</li><li>不需要数学系水平，但**同余、群/环/域的基本概念、常用算法（快速幂、扩展欧几里得、中国剩余定理）**要能随手推导。</li></ul>',10)])])}const u=a(l,[["render",o]]);export{b as __pageData,u as default};
